import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Classi contigue di numeri razionali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fn/fnf.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fn/fnf.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fn/fnf.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="classi-contigue-di-numeri-razionali" tabindex="-1">Classi contigue di numeri razionali <a class="header-anchor" href="#classi-contigue-di-numeri-razionali" aria-label="Permalink to “Classi contigue di numeri razionali”">​</a></h1><p>Ora esponiamo con rigore matematico quanto fatto intuitivamente nella pagina precedente: introduciamo il concetto di <strong>classi contigue</strong>.</p><p>Diremo che due insiemi di numeri (razionali nel nostro caso) formano due <strong>classi contigue</strong> se:</p><ul><li>gli insiemi sono <strong>separati</strong>: cioè ogni elemento della prima classe è sempre inferiore di ogni elemento della seconda classe;</li><li>gli insiemi godono dell&#39;<strong>avvicinamento indefinito</strong>: cioè posso scegliere un elemento del primo insieme ed un elemento del secondo insieme in modo che la loro differenza sia minore di un qualunque numero piccolissimo a piacere.</li></ul><p><a href="./fnfa.html">Esempio sulle proprietà di due classi contigue</a></p><blockquote><p><strong>[Teorema]{.text-red}</strong></p><p>Senza dimostrazione</p><p class="text-blue">[Due classi contigue ammettono uno ed un solo elemento separatore]</p></blockquote><p>Il problema era di riuscire a definire i nuovi numeri utilizzando esclusivamente i numeri razionali che già conoscevamo.</p><p>Arrivati a questo punto possiamo finalmente definire il <strong>[Numero Reale]{.text-red}</strong> utilizzando le classi contigue di numeri razionali.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};